      "search": "новый пользователь: документы и телефон qa.entry[0] · custom:start_consent  👋 <b>добро пожаловать!</b>\n\n🛡 получите <b>расширенную гарантию</b> на наш товар и билет в ежемесячный розыгрыш призов.\n\n📱 поделитесь номером телефона и ответьте на три коротких вопроса. сразу после заполнения профиля оформим гарантию и билет — без скриншотов и номера заказа.\n\n📃 <a href=\"https://disk.yandex.ru/i/i9otyqfxud1gqa\">публичная оферта</a>\n🔒 <a href=\"https://disk.yandex.ru/i/mbg7iphjzylvxq\">политика обработки данных</a>\n✍️ <a href=\"https://disk.yandex.ru/i/deokzm14xidf4w\">согласие на обработку данных</a>\n📣 <a href=\"https://disk.yandex.ru/i/1e_4dzrd4qx-zg\">согласие на рассылку</a>\n\n✅ нажимая кнопку ниже, вы подтверждаете, что ознакомились с документами и правилами.  я бы делала на ты, и живее: 🛡 здесь мы активируем гарантию 12 месяцев на товар, купленный у нас, и даем билет на наш ежемесячный розыгрыш призов📱 чтобы активировать гарантию, поделись номером телефона и прими стандартные документы✅ нажимая кнопку ниже, ты подтверждаешь, что ознакомлен с документами и правилами."
