      "search": "согласие на уведомления о раздачах qa.warranty[27] · qa.lambda: _giveaways_offer_reply(true), 🔔 <b>готово, будем присылать.</b>\n\n🎁 пришлём карточку, как только появится новый товар с кэшбэком.\n\n<i>отключить можно в «раздачи → уведомления».</i>\n\n👇 <b>выберите раздел:</b>\n\n🛡 <b>гарантия и билет</b> — статус расширенной гарантии и ваш номер для участия в розыгрыше.\n🎁 <b>раздачи</b> — выбрать товар и вернуть часть суммы сертификатом или продолжить заявку.\n🎬 <b>как поклеить</b> — короткие видео для телефона и планшета, чтобы обошлось без пузырей.\n🏆 <b>топ призов</b> — что разыгрываем в этом месяце и кто забирал раньше.\n🤝 <b>магазины партнёров</b> — наши партнёры на маркетплейсах, чтобы покупать у проверенного продавца.\n💬 <b>техподдержка</b> — любой вопрос: товар, гарантия, возврат, обмен, раздачи.\n\n<i>один заполненный профиль — один билет. повторно подтверждать покупку не нужно.</i> 🔔 отлично, договорились!отключить всегда можно в меню: «раздачи → уведомления»👌🏆 топ призов🤝 магазины партнёров "
