          "text": "<b>📱 Стекло на телефон</b>\n\n<b>1. Подготовьте экран</b>\nОчистите его влажной салфеткой, вытрите насухо и удалите пыль клейким стикером.\n\n<b>2. Установите рамку</b>\nПоложите устройство на ровную поверхность и установите рамку так, как показано в ролике.\n\n<b>3. Наклейте стекло</b>\nПотяните за язычок или нажмите на область запуска по инструкции из ролика. Не сдвигайте рамку во время установки.\n\n<b>4. Снимите рамку</b>\nПодождите несколько секунд, аккуратно снимите рамку и разгладьте оставшийся воздух от центра к краям.\n\n🔁 Не получилось с первого раза — напишите в 💬 Техподдержку, разберёмся.\n👇 Другие ролики — кнопка ниже.",
