          "owner": "message",
          "method": "answer_video",
          "text": "<b>💧 Плёнка на телефон</b>\n\n<b>1. Подготовьте экран</b>\nОчистите экран салфетками и удалите оставшиеся частицы пыли клейким стикером.\n\n<b>2. Примерьте плёнку</b>\nНе снимая подложку полностью, совместите плёнку с краями экрана, динамиком и камерой.\n\n<b>3. Наклейте постепенно</b>\nОтделяйте подложку небольшими участками и разглаживайте плёнку ракелем от центра к краям.\n\n<b>4. Завершите установку</b>\nСнимите верхний транспортировочный слой и ещё раз аккуратно разгладьте поверхность.\n\n🔁 Не получилось с первого раза — напишите в 💬 Техподдержку, разберёмся.\n👇 Другие ролики — кнопка ниже.",
